struct P {
    long long x, y;
    P operator+(const P &o) const { return {x + o.x, y + o.y}; }
    P operator-(const P &o) const { return {x - o.x, y - o.y}; }
    P operator*(long long k) const { return {x * k, y * k}; }
    bool operator==(const P &o) const { return x == o.x && y == o.y; }
    bool operator<(const P &o) const { return x != o.x ? x < o.x : y < o.y; }
    long long cross(const P &o) const { return x * o.y - y * o.x; }   // iloczyn wektorowy
    long long dot(const P &o) const { return x * o.x + y * o.y; }     // iloczyn skalarny
    long long norm2() const { return x * x + y * y; }                 // kwadrat długości
};

