struct P {
    long long x, y;
    P operator+(const P &o) const { return {x + o.x, y + o.y}; }
    P operator-(const P &o) const { return {x - o.x, y - o.y}; }
    P operator*(long long k) const { return {x * k, y * k}; }
    bool operator==(const P &o) const { return x == o.x && y == o.y; }
    bool operator<(const P &o) const { return x != o.x ? x < o.x : y < o.y; }
    long long cross(const P &o) const { return x * o.y - y * o.x; }   // iloczyn wektorowy
    long long dot(const P &o) const { return x * o.x + y * o.y; }     // iloczyn skalarny
    long long norm2() const { return x * x + y * y; }                 // kwadrat długości
};

istream &operator>>(istream &in, P &p) { return in >> p.x >> p.y; }
ostream &operator<<(ostream &out, const P &p) { return out << p.x << " " << p.y; }
double dist(P a, P b) { return sqrt((double)(a - b).norm2()); }

int main() {
    P a, b, c;
    cin >> a >> b >> c;
    cout << a + b << "\n";                    // suma wektorów
    cout << b - a << "\n";                    // wektor AB
    cout << (b - a).dot(c - a) << "\n";       // iloczyn skalarny AB·AC
    cout << (b - a).cross(c - a) << "\n";     // iloczyn wektorowy AB×AC
    cout << fixed << setprecision(6) << dist(a, b) << "\n";
    vector<P> v = {a, b, c};
    sort(v.begin(), v.end());                 // po x, przy remisie po y
    for (auto &p : v) cout << p << " | ";
    cout << "\n";
}

