#include <bits/stdc++.h>
using namespace std;

struct P {
    long long x, y;
    P operator+(const P &o) const { return {x + o.x, y + o.y}; }
    P operator-(const P &o) const { return {x - o.x, y - o.y}; }
    P operator*(long long k) const { return {x * k, y * k}; }
    bool operator==(const P &o) const { return x == o.x && y == o.y; }
    bool operator<(const P &o) const { return x != o.x ? x < o.x : y < o.y; }
    long long cross(const P &o) const { return x * o.y - y * o.x; }   // iloczyn wektorowy
    long long dot(const P &o) const { return x * o.x + y * o.y; }     // iloczyn skalarny
    long long norm2() const { return x * x + y * y; }                 // kwadrat długości
};

int sgn(long long v) { return (v > 0) - (v < 0); }

// Czy p leży na odcinku [a, b] (końce włącznie)?
bool onSegment(P p, P a, P b) {
    return (b - a).cross(p - a) == 0 && (a - p).dot(b - p) <= 0;
}

// Czy odcinki [a, b] i [c, d] mają punkt wspólny (końce włącznie)?
bool segmentsIntersect(P a, P b, P c, P d) {
    int d1 = sgn((b - a).cross(c - a)), d2 = sgn((b - a).cross(d - a));
    int d3 = sgn((d - c).cross(a - c)), d4 = sgn((d - c).cross(b - c));
    if (d1 * d2 < 0 && d3 * d4 < 0) return true;        // przecięcie "na krzyż"
    return onSegment(c, a, b) || onSegment(d, a, b) ||   // dotknięcia i przypadki
           onSegment(a, c, d) || onSegment(b, c, d);     // współliniowe
}

int main() {
    int q;
    cin >> q;
    while (q--) {
        P a, b, c, d;
        cin >> a.x >> a.y >> b.x >> b.y >> c.x >> c.y >> d.x >> d.y;
        cout << (segmentsIntersect(a, b, c, d) ? "TAK" : "NIE") << "\n";
    }
}

