#include <bits/stdc++.h>
using namespace std;

struct P {
    long long x, y;
    P operator+(const P &o) const { return {x + o.x, y + o.y}; }
    P operator-(const P &o) const { return {x - o.x, y - o.y}; }
    P operator*(long long k) const { return {x * k, y * k}; }
    bool operator==(const P &o) const { return x == o.x && y == o.y; }
    bool operator<(const P &o) const { return x != o.x ? x < o.x : y < o.y; }
    long long cross(const P &o) const { return x * o.y - y * o.x; }   // iloczyn wektorowy
    long long dot(const P &o) const { return x * o.x + y * o.y; }     // iloczyn skalarny
    long long norm2() const { return x * x + y * y; }                 // kwadrat długości
};

// Odległość punktu p od PROSTEJ przez a i b (a != b).
double distToLine(P p, P a, P b) {
    return fabs((double)(b - a).cross(p - a)) / sqrt((double)(b - a).norm2());
}

// Odległość punktu p od ODCINKA [a, b].
double distToSegment(P p, P a, P b) {
    if (a == b) return sqrt((double)(p - a).norm2());
    if ((b - a).dot(p - a) <= 0) return sqrt((double)(p - a).norm2());   // rzut przed a
    if ((a - b).dot(p - b) <= 0) return sqrt((double)(p - b).norm2());   // rzut za b
    return distToLine(p, a, b);                                          // rzut wewnątrz
}

int main() {
    int q;
    cin >> q;
    cout << fixed << setprecision(6);
    while (q--) {
        P p, a, b;
        cin >> p.x >> p.y >> a.x >> a.y >> b.x >> b.y;
        cout << distToLine(p, a, b) << " " << distToSegment(p, a, b) << "\n";
    }
}

// Rzut punktu p na prostą ab (a != b) — spodek prostopadłej.
pair<double, double> projectOnLine(double px, double py, double ax, double ay, double bx, double by) {
