int sgnEps(double x) { return (x > EPS) - (x < -EPS); }

int main() {
    double a = 0.1 + 0.2;
    cout << (a == 0.3) << " " << (fabs(a - 0.3) < EPS) << "\n";   // 0 1

    double c = 1.0 + 1e-15;                    // "cosinus" minimalnie > 1 przez zaokrąglenia
    cout << isnan(acos(c)) << " " << acos(max(-1.0, min(1.0, c))) << "\n";   // 1 0

    double tiny = -0.0001;
    printf("%.3f ", tiny);                     // -0.000  (ujemne zero na wyjściu!)
    if (fabs(tiny) < 5e-4) tiny = 0;
    printf("%.3f\n", tiny);                    // 0.000

    cout << fixed << setprecision(6) << acos(-1.0) << " " << sgnEps(1e-12) << "\n";   // 3.141593 0
}

